#include <iostream>

int grupos_completos(int cantidad, int capacidad) {
    return cantidad / capacidad;
}

int main() {
    const int cantidad = 23;
    const int capacidad = 5;
    const int q = grupos_completos(cantidad, capacidad);
    const int r = cantidad % capacidad;
    const bool cumple = (q * capacidad + r == cantidad)
        && (r >= 0) && (r < capacidad);
    std::cout << q << " " << r << " " << cumple;
    return 0;
}

